import{_ as o,a as r,b as t}from"./chunks/exprx.CcoobiI_.js";import{_ as l}from"./chunks/sh5._o0Xe7oD.js";import{_ as i,c as e,o as n,ae as s}from"./chunks/framework.CDjunVez.js";const q=JSON.parse('{"title":"指挥棒","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/conductor_wand.md","filePath":"zh/manual/conductor_wand.md"}'),d={name:"zh/manual/conductor_wand.md"};function c(h,a,_,u,g,m){return n(),e("div",null,[...a[0]||(a[0]=[s('<h1 id="指挥棒" tabindex="-1">指挥棒 <a class="header-anchor" href="#指挥棒" aria-label="Permalink to &quot;指挥棒&quot;">​</a></h1><p><strong>指挥棒</strong> 是专为大规模音符盒工程设计的工具，允许玩家像使用 WorldEdit 一样选择选区，并对选区内的所有扩展音符盒进行批量属性编辑。</p><h2 id="基础操作" tabindex="-1">基础操作 <a class="header-anchor" href="#基础操作" aria-label="Permalink to &quot;基础操作&quot;">​</a></h2><h3 id="_1-选区选择" tabindex="-1">1. 选区选择 <a class="header-anchor" href="#_1-选区选择" aria-label="Permalink to &quot;1. 选区选择&quot;">​</a></h3><ul><li><strong>设置点 1 (Pos1)</strong>: 拿着指挥棒 <strong>左键点击</strong> 方块。 <img src="'+o+'" alt="Pos1"></li><li><strong>设置点 2 (Pos2)</strong>: 拿着指挥棒 <strong>右键点击</strong> 方块。 <img src="'+r+'" alt="Pos2"></li><li>选区完成后，屏幕会显示选定的范围。</li><li>按住 Backspace 键可以取消选区。</li></ul><h3 id="_2-打开编辑界面" tabindex="-1">2. 打开编辑界面 <a class="header-anchor" href="#_2-打开编辑界面" aria-label="Permalink to &quot;2. 打开编辑界面&quot;">​</a></h3><ul><li>在选定两个点后，按下 Enter 键可打开指挥棒界面。 <img src="'+l+'" alt="ConductorScreen"><img src="'+t+'" alt="ExprX"></li></ul><h2 id="批量编辑功能" tabindex="-1">批量编辑功能 <a class="header-anchor" href="#批量编辑功能" aria-label="Permalink to &quot;批量编辑功能&quot;">​</a></h2><p>界面中列出了扩展音符盒的所有可编辑参数。每个参数前都有一个<strong>模式切换按钮</strong>：</p><h3 id="编辑模式详解" tabindex="-1">编辑模式详解 <a class="header-anchor" href="#编辑模式详解" aria-label="Permalink to &quot;编辑模式详解&quot;">​</a></h3><ul><li><strong>保持 (K)</strong>: 不修改该项参数，保留方块原有的值。</li><li><strong>设置 (=)</strong>: 将选区内所有方块的该参数统一修改为输入的值。</li><li><strong>增加 (+)</strong>: 在方块原有值的基础上增加输入的值（例如：将所有音符统一提高一个八度 +12）。</li><li><strong>减少 (-)</strong>: 在原有值基础上减去输入的值。</li><li><strong>乘法 (x)</strong> / <strong>除法 (/)</strong>: 按倍率缩放参数（常用于力度或延迟的百分比调整）。</li></ul><h3 id="支持的参数" tabindex="-1">支持的参数 <a class="header-anchor" href="#支持的参数" aria-label="Permalink to &quot;支持的参数&quot;">​</a></h3><ul><li>音高 (Note)</li><li>力度 (Velocity)</li><li>延音 (Sustain)</li><li>播放延迟 (Delay)</li><li>淡入/淡出时间</li><li>高级模式中的属性</li></ul><h2 id="实用建议" tabindex="-1">实用建议 <a class="header-anchor" href="#实用建议" aria-label="Permalink to &quot;实用建议&quot;">​</a></h2><ol><li><strong>快速移调</strong>: 选定乐段后，使用“增加 (Add)”模式输入 <code>12</code> 或 <code>-12</code> 即可快速实现升降八度。</li><li><strong>渐变力度</strong>: 先统一设置一个基础力度，再配合高级模式的包络线进行细化。</li><li><strong>整体对齐</strong>: 如果发现乐段抢拍，可以使用“增加 (Add)”模式给延迟 (Delay) 增加统一的正偏差。</li></ol>',15)])])}const P=i(d,[["render",c]]);export{q as __pageData,P as default};
